/** Real v15 frames generated by mo-skia-sys/tests/outer_shadow.rs. */
import fs from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const [fixtures,componentPath,tsPath]=process.argv.slice(2);
assert(fixtures && componentPath && tsPath);
const {RasterComponent}=await import(pathToFileURL(path.resolve(tsPath,'index.js')));
const {default:factory}=await import(pathToFileURL(path.resolve(componentPath,'mo-skia.mjs')));
const component=await RasterComponent.create(factory,await WebAssembly.compile(await fs.readFile(path.join(componentPath,'mo-skia.wasm'))));
assert(component.supportsOuterShadows);
let count=0;
for(const name of (await fs.readdir(fixtures)).filter(n=>n.endsWith('.json')).sort()){
 const fixture=JSON.parse(await fs.readFile(path.join(fixtures,name)));
 const frame=Uint32Array.from(fixture.frame);
 assert.equal(frame[1],15);
 const result=component.raster(frame);
 assert.equal(result.status,0,name);
 assert.deepEqual(Array.from(result.pixels),fixture.pixels,name);
 count++;
}
assert.equal(count,5);
console.log(JSON.stringify({status:'passed',cases:count,comparison:'native and WASM pixels identical'}));
